    tenant_cols=_safe_columns(conn,'tenants')
    updates={k:v for k,v in tenant.items() if k in tenant_cols and k!='id'}
    if updates:
        conn.execute('UPDATE tenants SET '+','.join(f'{k}=?' for k in updates)+' WHERE id=?',tuple(updates.values())+(tenant_id,))
