  <div class="grid stats cop-stats">${metric('Qualified Intelligence',m.qualified_intelligence)}${metric('Items Requiring Attention',m.priority_actions)}${metric('Decisions Awaiting You',m.pending_member_decisions)}${metric('Active Operations',m.active_operations)}</div>
