function metric(label,value){return `<div class="card metric"><span>${label}</span><strong>${value}</strong></div>`}
function table(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="subtle">No records yet.</td></tr>`}</tbody></table>`}
async function addCopMessage(id){const body=prompt('Shared message:');if(!body)return;await api(`/api/salcapa/coordination/threads/${id}/messages`,{method:'POST',body:JSON.stringify({body,audience:'Shared'})});render();}
async function assignCopThread(id){const assigned_contact=prompt('Assigned Salus contact:');if(!assigned_contact)return;const member_contact_summary=prompt('Member-facing contact information:');if(!member_contact_summary)return;await api(`/api/salcapa/coordination/threads/${id}/assign`,{method:'POST',body:JSON.stringify({assigned_contact,member_contact_summary})});render();}
