async function relationOptions(fields){
  const result={};
  const defs=fields.filter(f=>f[2]==='relation');
  await Promise.all(defs.map(async f=>{const cfg=f[3]||{}; result[f[0]]=await api(`/api/${cfg.source}?assessment_id=${activeAssessmentId}`);}));
  return result;
}
function relationLabel(row,cfg){
  if(cfg.format==='gap') return `#${row.id} · ${row.severity||''} · ${row.description||''}`;
  const text=row[cfg.label]||`#${row.id}`;
  return `#${row.id} · ${text}`;
}
async function entityView(key){
  const c=configs[key];
  if(key!=='assessments'&&!activeAssessmentId){const a=await getActiveAssessment();if(!a){$('#content').innerHTML='<div class="notice">Create an assessment first.</div>';return;}}
  const rows=await api(scopedUrl(key));
  const edit=editingRecord&&editingRecord.key===key?rows.find(r=>r.id===editingRecord.id):null;
  const displayFields=edit?c.fields.filter(f=>!(f[3]?.createOnly)):c.fields;
  const relations=await relationOptions(displayFields);
  const immutable=key==='decisions';
  const defaults=edit||{};
  const canCreate=c.allowCreate!==false;
  const integrityNotice=key!=='assessments'?'<div class="subtle" style="margin-bottom:10px">Assessment ownership is controlled by the active assessment. Related records are limited to this assessment and cannot be reassigned across assessments.</div>':'';
  const evidenceNotice=key==='evidence'?'<div class="subtle" style="margin-bottom:10px">Verification and lifecycle are separate controls. Validity is set when evidence is created; once stale, restoring Current status requires the governed Lifecycle Review action.</div>':'';
  const editor=(!canCreate&&!edit)?`<div class="notice"><strong>Accountable acceptance only.</strong><br>Accepted-risk records are created automatically from an authorized Executive Decision of <em>Accept Risk</em>. They cannot be deleted; close or supersede them with a documented basis.</div>`:`<div class="section-title"><h2>${edit?'Edit':'New'} ${c.title}</h2>${edit?'<button class="btn secondary" type="button" onclick="cancelEdit()">Cancel</button>':''}</div>${integrityNotice}${evidenceNotice}${immutable?'<div class="subtle" style="margin-bottom:10px">Executive decisions are append-only records. An Accept Risk decision requires a named authority, explicit residual exposure, and review date; it automatically creates an accountable Accepted Risk record.</div>':''}<form id="entity-form">${formHtml(displayFields,defaults,relations)}<div class="form-actions"><button class="btn">${edit?'Update':'Save'} ${c.title}</button></div></form>`;
  $('#content').innerHTML=`<div class="split"><div class="card">${editor}</div><div><div class="section-title"><h2>${c.title} Register</h2><span class="subtle">${rows.length} records</span></div>${entityTable(key,c,rows)}</div></div>`;
  const form=$('#entity-form');
  if(form&&key==='capabilities'){const mt=form.elements.measurement_type,cmp=form.elements.comparator;if(mt&&cmp){const sync=()=>{if(mt.value==='Binary')cmp.value='=';};mt.onchange=sync;sync();}}
  if(form) form.onsubmit=async e=>{e.preventDefault(); const data={}; new FormData(e.target).forEach((v,k)=>{const field=c.fields.find(f=>f[0]===k); const type=field?.[2]; if(v===''){if(type==='relation')data[k]=null;return;} data[k]=(type==='number'||type==='relation')?Number(v):v}); if(!edit&&key!=='assessments')data.assessment_id=activeAssessmentId; if(!edit&&key==='decisions')data.authority=currentUser; if(edit) await api(`/api/${key}/${edit.id}`,{method:'PUT',body:JSON.stringify(data)}); else {const created=await api('/api/'+key,{method:'POST',body:JSON.stringify(data)}); if(key==='assessments'){activeAssessmentId=created.id;localStorage.setItem('salus_assessment_id',String(created.id));await renderAssessmentSelector();}} editingRecord=null; render();};
}
function formHtml(fields,record={},relations={}){return `<div class="form-grid">${fields.map(f=>{const [name,label,type,opt]=f; const wide=type==='textarea'?'wide':''; const val=record[name]??''; if(type==='select') return `<label class="${wide}">${label}<select name="${name}">${opt.map(o=>`<option ${String(o)===String(val)?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`; if(type==='relation'){const cfg=opt||{};const rows=relations[name]||[];const empty=cfg.required?'':`<option value="">None / Not linked</option>`;const options=rows.map(r=>`<option value="${r.id}" ${String(r.id)===String(val)?'selected':''}>${esc(relationLabel(r,cfg))}</option>`).join('');return `<label>${label}<select name="${name}" ${cfg.required?'required':''}>${empty}${options||'<option value="">No eligible records available</option>'}</select></label>`;} if(type==='textarea') return `<label class="${wide}">${label}<textarea name="${name}" ${opt===1?'required':''}>${esc(val)}</textarea></label>`; return `<label class="${wide}">${label}<input name="${name}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(val)}" ${opt===1?'required':''}></label>`}).join('')}</div>`}
function entityTable(key,c,rows){
  let headers=c.cols.map(x=>x.replaceAll('_',' ')); headers.push('');
  return table(headers,rows.map(r=>[...c.cols.map(col=>{let v=r[col]; if(col==='status'||col==='severity'||col==='confidence'||col==='verification_status'||col==='lifecycle_status'||col==='review_lifecycle_status'||col==='reassessment_lifecycle_status'||col==='decision_type') return badge(v); if(col.includes('cost')||col==='funding_authorized') return fmtMoney(v); if(col==='priority_score') return Number(v||0).toFixed(1); if(col==='attainment_percent') return Number(v||0).toFixed(1)+'%'; if(col==='target_status') return badge(v); if(col==='scope_locked') return v?'Locked':'Open'; return esc(v)}),
    key==='decisions'?`<div class="row-actions"><span class="subtle">Immutable</span><button class="btn secondary" onclick="reviewExecutiveDecision(${r.id},'${esc(r.review_date||'')}')">Controlled Review</button></div>`:
    key==='assessments'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('assessments',${r.id})">Edit</button><button class="btn secondary" onclick="reviewAssessmentReassessment(${r.id},'${esc(r.reassessment_date||'')}')">Reassessment Review</button></div>`:
    key==='evidence'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('evidence',${r.id})">Edit</button><button class="btn secondary" onclick="reviewEvidenceLifecycle(${r.id},'${esc(r.valid_until||'')}')">Lifecycle Review</button><button class="btn secondary" onclick="del('evidence',${r.id})">Delete</button></div>`:
    key==='gaps'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('gaps',${r.id})">Edit</button><button class="btn secondary" onclick="transitionGap(${r.id},'${esc(r.status)}')">Change State</button></div>`:
    key==='improvements'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('improvements',${r.id})">Edit</button><button class="btn secondary" onclick="transitionImprovement(${r.id},'${esc(r.status)}')">Change State</button></div>`:
    key==='accepted_risks'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('accepted_risks',${r.id})">Update Record</button>${r.status==='Active'||r.status==='Under Review'?`<button class="btn secondary" onclick="transitionAcceptedRisk(${r.id},'${esc(r.status)}')">Change State</button><button class="btn secondary" onclick="reviewAcceptedRisk(${r.id},'${esc(r.review_date||'')}')">Controlled Review</button>`:'<span class="subtle">Terminal record</span>'}</div>`:
    c.allowDelete===false?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('${key}',${r.id})">Review / Update</button></div>`:`<div class="row-actions"><button class="btn secondary" onclick="editEntity('${key}',${r.id})">Edit</button><button class="btn secondary" onclick="del('${key}',${r.id})">Delete</button></div>`]));
}
function editEntity(key,id){editingRecord={key,id}; entityView(key)}
function cancelEdit(){editingRecord=null; render()}
async function del(k,id){if(!confirm('Delete this record? This action is audit logged.')) return; await api(`/api/${k}/${id}`,{method:'DELETE'}); editingRecord=null; render();}
async function reviewEvidenceLifecycle(id,currentValidUntil=''){const validUntil=prompt('New valid-until date (YYYY-MM-DD). This controlled review restores lifecycle status to Current.',currentValidUntil||'');if(!validUntil)return;const note=prompt('Document the lifecycle review basis / validation performed:','');if(!note)return;await api(`/api/evidence/${id}/lifecycle-review`,{method:'POST',body:JSON.stringify({valid_until:validUntil,review_note:note})});render();}
