async function riskAnalytics(){
  const a=await getActiveAssessment(); if(!a){$('#content').innerHTML='<div class="notice">Create an assessment first.</div>';return}
  const id=a.id; const [rows,evidence,overrides]=await Promise.all([api('/api/risk/'+id),api('/api/evidence?assessment_id='+id),api('/api/risk_overrides?assessment_id='+id)]);
  const verified=evidence.filter(e=>e.verification_status==='Verified'&&e.lifecycle_status==='Current');
  const effectiveEvidenceIds=new Set(verified.map(e=>e.id));
  const canDecide=!!(accessState?.permissions||[]).includes('decide');
  let panel='';
  if(overridingThreatId){
    const r=rows.find(x=>x.threat_id===overridingThreatId);
    panel=`<div class="card" style="margin-bottom:16px"><div class="section-title"><h2>Record Professional Risk Judgment — ${esc(r?.name||'')}</h2><button class="btn secondary" onclick="cancelRiskOverride()">Cancel</button></div><p class="subtle">This action does not alter calculated current, predicted residual, or validated residual risk. The authenticated actor is recorded as authority. A future review date is required; an overdue judgment stops supplying assigned risk until controlled review.</p><form id="risk-override-form"><div class="form-grid"><label>Calculated Current Risk<input value="${esc((r?.current_band||'')+' '+(r?.current_score??''))}" disabled></label><label>Assigned Risk Score (0–100)<input type="number" min="0" max="100" step="0.1" name="assigned_score" required></label><label>Review Date<input type="date" name="review_date" required></label><label>Supporting Verified Evidence<select name="evidence_id"><option value="">None</option>${verified.map(e=>`<option value="${e.id}">#${e.id} — ${esc(e.title)}</option>`).join('')}</select></label></div><label>Reason / Professional Basis<textarea name="reason" required></textarea></label><div class="form-actions"><button class="btn">Record Professional Judgment</button></div></form></div>`;
  }
  const riskRows=rows.map(r=>{
    const applicable=r.professional_override;
    const record=r.professional_override_record;
    const action=canDecide?(record?`<div class="row-actions"><button class="btn secondary" onclick="beginRiskOverride(${r.threat_id})">Supersede</button><button class="btn secondary" onclick="withdrawRiskOverride(${record.id})">Withdraw</button></div>`:`<button class="btn secondary" onclick="beginRiskOverride(${r.threat_id})">Record Override</button>`):'<span class="subtle">Decision authority required</span>';
    const assigned=applicable?`${badge(r.assigned_risk_band)} ${r.assigned_risk_score}<br><span class="subtle">${esc(applicable.authority)} · ${esc(applicable.created_at)}</span>${applicable.evidence_id?'<br><span class="subtle">Supporting evidence Current</span>':''}`:record?`<span class="badge stale">Not Current</span><br><span class="subtle">${esc(r.professional_override_unavailable_reason)}</span>`:'—';
    return [esc(r.name),`${badge(r.inherent_band)} ${r.inherent_score}`,`${r.capability_effectiveness}%`,`${badge(r.current_band)} ${r.current_score}`,assigned,r.approved_improvements,r.validated_improvements,`${badge(r.predicted_residual_band)} ${r.predicted_residual_score}`,`${badge(r.validated_residual_band)} ${r.validated_residual_score}`,esc(r.risk_methodology_version),badge(r.confidence),badge(r.trend),action];
  });
  $('#content').innerHTML=panel+`<div class="notice"><strong>Calculated risk and professional judgment are separate records.</strong> Current risk is calculated from threat/scenario/capability data. A professional override records an assigned risk for decision context but never overwrites the calculated value and never changes predicted or validated residual-risk mathematics.</div>`+
  table(['Threat / Hazard','Inherent','Capability Effectiveness','Calculated Current','Professional Assigned','Approved','Validated','Predicted Residual','Validated Residual','Method','Confidence','Trend','Professional Judgment'],riskRows)+
  `<div class="section-title"><h2>Professional Risk Override History</h2><span class="subtle">${overrides.length} records</span></div>`+
  table(['ID','Status','Review Lifecycle','Threat','Calculated','Assigned','Authority','Reason','Evidence','Review Date','Created','Actions'],overrides.map(o=>{const evidenceEligible=o.evidence_id==null||effectiveEvidenceIds.has(o.evidence_id);const actions=o.status==='Active'?`<div class="row-actions">${evidenceEligible?`<button class="btn secondary" onclick="reviewRiskOverride(${o.id},'${esc(o.review_date||'')}')">Controlled Review</button>`:'<span class="badge stale">Restore evidence before review</span>'}<button class="btn secondary" onclick="withdrawRiskOverride(${o.id})">Withdraw</button></div>`:esc(o.withdrawn_reason||'');return [o.id,badge(o.status),badge(o.review_lifecycle_status||'Current'),o.threat_id,`${badge(o.calculated_band)} ${o.calculated_score}`,`${badge(o.assigned_band)} ${o.assigned_score}`,esc(o.authority),esc(o.reason),o.evidence_id||'—',esc(o.review_date),esc(o.created_at),actions]}));
  const form=$('#risk-override-form'); if(form) form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const evidenceId=fd.get('evidence_id');await api('/api/risk-overrides',{method:'POST',body:JSON.stringify({assessment_id:id,threat_id:overridingThreatId,assigned_score:Number(fd.get('assigned_score')),reason:fd.get('reason'),authority:currentUser,evidence_id:evidenceId?Number(evidenceId):null,review_date:fd.get('review_date')||''})});overridingThreatId=null;render();};
}
